using System;
using System.Collections;
using System.IO;
using System.Linq;
using System.Text;
using UnityEditor;
using UnityEditor.SceneManagement;
using UnityEngine;
using UnityEngine.UI;
using Object=UnityEngine.Object;
[InitializeOnLoad]public static class GridShiftV7FinalChecks {
 static GridShiftV7FinalChecks(){EditorApplication.playModeStateChanged+=s=>{if(s==PlayModeStateChange.EnteredPlayMode&&SessionState.GetBool("V7Final",false)){SessionState.SetBool("V7Final",false);new GameObject("Visual7Checks").AddComponent<GridShiftV7VisualChecks>();}};}
 [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.BeforeSceneLoad)]static void Prepare(){if(SessionState.GetBool("V7Final",false)){DeliverySaveStore.OverridePath=Path.GetFullPath("v7-visual-save.json");GridShiftTutorial.Prefix="GS.Visual7.Tutorial.";GridShiftTutorial.Reopen();GridShiftTutorial.Skip();}}
 public static void Batch(){var report=new StringBuilder();try{foreach(var name in new[]{"MainMenu","SampleScene","Office"}){EditorSceneManager.OpenScene("Assets/Scenes/"+name+".unity");foreach(var root in UnityEngine.SceneManagement.SceneManager.GetActiveScene().GetRootGameObjects())foreach(var t in root.GetComponentsInChildren<Transform>(true))if(GameObjectUtility.GetMonoBehavioursWithMissingScriptCount(t.gameObject)!=0)throw new Exception("Script ausente: "+t.name);report.AppendLine("PASS "+name+" sem scripts ausentes");}EditorSceneManager.OpenScene("Assets/Scenes/SampleScene.unity");var manager=Object.FindFirstObjectByType<DeliveryManager>();if(manager.points.Select(p=>p.id).Distinct().Count()!=manager.points.Length)throw new Exception("IDs duplicados");foreach(var p in manager.points){if(!p.Valid)throw new Exception("Ponto inválido: "+p.id);var a=p.route.pontos[p.segment].position;var direction=(p.route.pontos[p.segment+1].position-a).normalized;if(Vector3.Distance(a+direction*Vector3.Dot(p.Stop-a,direction),p.Stop)>.02f)throw new Exception("Parada fora da faixa");if(p.route.GetParada(out var line,out _)&&Vector3.Dot(line-p.Stop,direction)<11.9f)throw new Exception("Parada próxima da faixa de pedestres");}report.AppendLine("PASS "+manager.points.Length+" paradas acessíveis alinhadas às rotas e antes dos cruzamentos");DeliverySaveStore.OverridePath=Path.GetFullPath("v6-simulation-save.json");if(!DeliverySaveStore.Read(out var legacy)||legacy.orders.Count<3)throw new Exception("Save legado incompatível");report.AppendLine("PASS save 6.0 lido com campos novos opcionais");DeliverySaveStore.OverridePath=Path.GetFullPath("v7-core-save.json");if(!DeliverySaveStore.Read(out var updated)||updated.upgrades.Count<6)throw new Exception("Save 7.0 não preserva upgrades");report.AppendLine("PASS save 7.0 lido com níveis da empresa");report.AppendLine("RESULT SUCCESS");File.WriteAllText("v7-structure.txt",report.ToString());foreach(var weather in Object.FindObjectsByType<ClimaReal>(FindObjectsSortMode.None))weather.enabled=false;SessionState.SetBool("V7Final",true);EditorApplication.isPlaying=true;}catch(Exception e){File.WriteAllText("v7-structure.txt",report+"\nFAIL "+e);EditorApplication.Exit(1);}}
}
public sealed class GridShiftV7VisualChecks:MonoBehaviour {
 IEnumerator Start(){Application.runInBackground=true;Application.targetFrameRate=60;yield return new WaitForSecondsRealtime(4);var report=new StringBuilder();bool success=true;try{var manager=DeliveryManager.Instance;var p=Object.FindFirstObjectByType<PlayerMovement>();var controller=p.GetComponent<CharacterController>();controller.enabled=false;p.transform.SetPositionAndRotation(new Vector3(365,-4.23f,170),Quaternion.Euler(0,45,0));controller.enabled=true;var truck=manager.fleet.First(v=>v.kind==FleetKind.Truck);var allowed=manager.points.Where(t=>t.Valid&&manager.Progression.Unlocked(t)).ToArray();var pickup=allowed.Where(t=>DeliveryRouting.Find(truck.driver.RotaAtual,t.route,DeliveryRouting.Behind(truck.driver,t))!=null).OrderBy(t=>DeliveryRouting.Find(truck.driver.RotaAtual,t.route,DeliveryRouting.Behind(truck.driver,t)).Sum(DeliveryRouting.Length)).First();var dest=allowed.Where(t=>t!=pickup&&DeliveryRouting.Find(pickup.route,t.route)!=null).First();if(!manager.TryCreate(new DeliveryRequest{goods="Entrega de validação visual",weightKg=500,pickupId=pickup.id,destinationId=dest.id},out _,out var error))throw new Exception(error);manager.Dispatch();}catch(Exception e){success=false;report.AppendLine("FAIL "+e);}yield return new WaitForSecondsRealtime(1);var player=Object.FindFirstObjectByType<PlayerMovement>();var view=player.CameraTransform.GetComponent<Camera>();var ui=GridShiftOperationsUI.Instance;
  if(success){Capture(view,"cidade-hud-minimapa",false);ui.Open("map");yield return new WaitForSecondsRealtime(.4f);try{var mini=player.GetComponentInChildren<MinimapCamera>();if(!mini.Expanded||Mathf.Abs(mini.transform.eulerAngles.y)>.1f)throw new Exception("Mapa não está voltado ao norte");if(!ui.transform.Find("OperationOverlay/Panel/MapActions").gameObject.activeInHierarchy)throw new Exception("Ações de mapa ausentes");report.AppendLine("PASS mapa ampliado ao norte, ações visíveis e HUD oculto");Capture(view,"mapa-frota-destino",true);}catch(Exception e){success=false;report.AppendLine("FAIL "+e);}ui.Close();ui.Open("controls");yield return new WaitForSecondsRealtime(.3f);Capture(view,"controles",true);ui.Close();GridShiftTutorial.Reopen();ui.Open("tutorial");yield return new WaitForSecondsRealtime(.3f);Capture(view,"tutorial-etapas",true);ui.Close();GridShiftTutorial.Skip();ui.Open("upgrades");yield return new WaitForSecondsRealtime(.3f);Capture(view,"upgrades-unity",true);ui.Close();report.AppendLine("PASS capturas finais de HUD, mapa, controles, tutorial e upgrades");}
  report.AppendLine("RESULT "+(success?"SUCCESS":"FAILURE"));File.WriteAllText("v7-visual.txt",report.ToString());EditorApplication.Exit(success?0:1);
 }
 static void Capture(Camera view,string name,bool overlay){Directory.CreateDirectory("v7-final-images");var camera=new GameObject("FinalCapture7").AddComponent<Camera>();camera.CopyFrom(view);camera.enabled=false;camera.transform.SetPositionAndRotation(view.transform.position,view.transform.rotation);var canvases=overlay?Object.FindObjectsByType<Canvas>(FindObjectsSortMode.None).Where(c=>c.renderMode==RenderMode.ScreenSpaceOverlay).ToArray():Array.Empty<Canvas>();foreach(var c in canvases){c.renderMode=RenderMode.ScreenSpaceCamera;c.worldCamera=camera;c.planeDistance=.2f;}var rt=new RenderTexture(1920,1080,24);camera.targetTexture=rt;Canvas.ForceUpdateCanvases();camera.Render();var previous=RenderTexture.active;RenderTexture.active=rt;var image=new Texture2D(1920,1080,TextureFormat.RGB24,false);image.ReadPixels(new Rect(0,0,1920,1080),0,0);image.Apply();File.WriteAllBytes("v7-final-images/"+name+".png",image.EncodeToPNG());RenderTexture.active=previous;foreach(var c in canvases){c.renderMode=RenderMode.ScreenSpaceOverlay;c.worldCamera=null;}rt.Release();Destroy(rt);Destroy(image);Destroy(camera.gameObject);}
}
